t=df['t'].values; P=df['P'].values; y=df['dP_dt'].values
yP=y*P
sets={
 'A_tsin': lambda w: [t*P, P*P*np.log(P), np.ones_like(t), t, np.sin(w*t), np.cos(w*t), t*np.sin(w*t), t*np.cos(w*t)],
 'B_exp_log': lambda w: [t*P, P*P*np.log(P), np.ones_like(t), t, np.sin(w*t), np.cos(w*t), np.exp(-t), np.log(t)],
 'C_expsin': lambda w: [t*P, P*P*np.log(P), np.ones_like(t), t, np.sin(w*t), np.cos(w*t), np.exp(-t)*np.sin(w*t), np.exp(-t)*np.cos(w*t)],
 'D_sqrt': lambda w: [t*P, P*P*np.log(P), np.ones_like(t), t, np.sin(w*t), np.cos(w*t), np.sqrt(t), np.log(t)],
}
for k,f in sets.items():
    best=None
    for w in np.linspace(0.05,4,1500):
        X=np.column_stack(f(w)); c,_,_,_=np.linalg.lstsq(X,yP,rcond=None)
        r=yP-X@c; e=np.mean(r**2)/np.var(yP)
        if best is None or e<best[0]: best=(e,w,c)
    print(k, best[0], best[1], np.round(best[2],4))
